<?php
namespace EIPSI\StudyEngine\Management;
use EIPSI\StudyEngine\Persistence as P;
use EIPSI\StudyEngine\Contracts\Canonical;
/** Private database artifacts, optimistic snapshot, bounded work per explicit job step. */
final class Exports {
    const COLUMNS=array('study_id','cycle','study_version_id','participation_id','opportunity_id','occurrence','assessment_id','native_version_id','attempt_id','attempt_state','saved_at','item_id','response_key','variable_name','label','type','response_status','value','selected_option_id','definition_hash','data_policy');
    private $q;
    public function __construct(Query $q){$this->q=$q;}
    private function fingerprints(array $executions): array {
        if(!$executions)return array();$db=$this->q->db;$ids=implode(',',array_map(function($e)use($db){return $db->prepare('%s',$e['id']);},$executions));$native=array();
        if($this->q->nativeExists())foreach($db->rows('SELECT id,management_execution,revision,state,SHA2(COALESCE(metadata_json,\'\'),256) AS metadata_hash,SHA2(binding_json,256) AS binding_hash,SHA2(COALESCE(final_json,\'\'),256) AS final_hash,SHA2(COALESCE(partial_json,\'\'),256) AS partial_hash FROM '.$db->table('native_executions').' WHERE management_execution IN ('.$ids.') ORDER BY id') as $row){$execution=$row['management_execution'];unset($row['management_execution']);$native[$execution][]=$row;}
        $participants=array();foreach($db->rows('SELECT p.id,p.updated_at,p.email,p.archived_email,p.privacy_state FROM '.$db->table('participants').' p JOIN '.$db->table('study_executions').' e ON e.participant_id=p.id WHERE e.id IN ('.$ids.')') as $p){$id=$p['id'];unset($p['id']);$participants[$id]=$p;}
        $out=array();foreach($executions as $e)$out[$e['id']]=hash('sha256',Canonical::json(array($e['revision'],$e['checkpoint_hash'],$e['data_policy'],$e['finalized_at'],$participants[$e['participant_id']]??null,$native[$e['id']]??array())));return $out;
    }
    private function fingerprint(array $e): string {return $this->fingerprints(array($e))[$e['id']];}
    public function create(array $f,string $kind,string $request): array {
        $f=Query::filters($f);unset($f['cursor'],$f['limit'],$f['science_before'],$f['decision_after'],$f['identity']);if(!in_array($kind,array('responses','progress','dictionary','audit','identities','randomizations'),true))throw new \DomainException('MANAGEMENT_EXPORT_KIND_INVALID');\EIPSI\StudyEngine\Contracts\Check::id($request,'request');
        $spec=array('filters'=>$f,'kind'=>$kind);$db=$this->q->db;$study=$this->q->study;
        return $db->transactional(function()use($db,$study,$spec,$f,$request){
            $db->query("UPDATE ".$db->table('management_exports')." SET payload_json=NULL,plan_json='[]',state='EXPIRED' WHERE expires_at<UTC_TIMESTAMP() AND state<>'EXPIRED'");
            $old=$db->row($db->prepare('SELECT * FROM '.$db->table('management_exports').' WHERE actor_id=%d AND request_id=%s FOR UPDATE',get_current_user_id(),$request));if($old){if($old['study_id']!==$study||Canonical::json(array_diff_key(P\Database::json($old['spec_json']),array('cutoff_event'=>true,'cutoff_at'=>true)))!==Canonical::json($spec))throw new P\PersistenceConflict('EXPORT_REQUEST_REUSED');return $this->status($old);}
            $executions=$db->rows('SELECT e.id,e.participant_id,e.revision,e.checkpoint_hash,e.data_policy,e.finalized_at FROM '.$db->table('study_executions').' e WHERE '.$this->q->scope($f,$spec['kind']!=='audit').' ORDER BY e.id');$plan=array();$hashes=$this->fingerprints($executions);foreach($executions as $e)$plan[]=array('id'=>$e['id'],'hash'=>$hashes[$e['id']]);
            $spec['cutoff_at']=gmdate('Y-m-d H:i:s');$spec['cutoff_event']=(int)($db->row('SELECT MAX(id) AS n FROM '.$db->table('management_events'))['n']??0);$id='MX_'.bin2hex(random_bytes(16));$now=gmdate('Y-m-d H:i:s');$db->insert('management_exports',array('id'=>$id,'study_id'=>$study,'actor_id'=>get_current_user_id(),'request_id'=>$request,'state'=>'PENDING','created_at'=>$now,'expires_at'=>gmdate('Y-m-d H:i:s',time()+3600),'spec_json'=>Canonical::json($spec),'plan_json'=>Canonical::json($plan),'cursor_position'=>0,'payload_json'=>'[]'));
            Audit::record($study,'EXPORT_REQUESTED',null,$id,array('kind'=>$spec['kind'],'count'=>count($plan),'request_id'=>$request));return $this->status($this->row($id));
        });
    }
    private function row(string $id,bool $lock=false): array {\EIPSI\StudyEngine\Contracts\Check::id($id,'export');$r=$this->q->db->row($this->q->db->prepare('SELECT * FROM '.$this->q->db->table('management_exports').' WHERE id=%s AND study_id=%s AND actor_id=%d'.($lock?' FOR UPDATE':''),$id,$this->q->study,get_current_user_id()));if(!$r)throw new \DomainException('MANAGEMENT_EXPORT_NOT_FOUND');return $r;}
    private function status(array $r): array {return array('id'=>$r['id'],'state'=>$r['expires_at']<gmdate('Y-m-d H:i:s')?'EXPIRED':$r['state'],'created_at'=>$r['created_at'],'expires_at'=>$r['expires_at'],'processed'=>(int)$r['cursor_position'],'total'=>count(P\Database::json($r['plan_json'])),'error'=>$r['error_code'],'manifest'=>$r['manifest_json']===null?null:P\Database::json($r['manifest_json']));}
    public function jobs(): array {$rows=$this->q->db->rows($this->q->db->prepare('SELECT id,study_id,actor_id,state,created_at,expires_at,cursor_position,plan_json,manifest_json,error_code FROM '.$this->q->db->table('management_exports').' WHERE study_id=%s AND actor_id=%d ORDER BY created_at DESC LIMIT 20',$this->q->study,get_current_user_id()));return array_map(function($r){return $this->status($r);},$rows);}
    private function valid(array $plan): bool {if(!$plan)return true;$db=$this->q->db;$ids=implode(',',array_map(function($p)use($db){return $db->prepare('%s',$p['id']);},$plan));$executions=$db->rows('SELECT e.id,e.participant_id,e.revision,e.checkpoint_hash,e.data_policy,e.finalized_at FROM '.$db->table('study_executions').' e WHERE '.$db->prepare('e.study_id=%s',$this->q->study).' AND e.id IN ('.$ids.')');if(count($executions)!==count($plan))return false;$hashes=$this->fingerprints($executions);foreach($plan as $p)if(!isset($hashes[$p['id']])||!hash_equals($p['hash'],$hashes[$p['id']]))return false;return true;}
    private function lockPlan(array $plan): void {if(!$plan)return;$db=$this->q->db;$ids=implode(',',array_map(function($p)use($db){return $db->prepare('%s',$p['id']);},$plan));$db->rows('SELECT e.id FROM '.$db->table('study_executions').' e WHERE '.$db->prepare('e.study_id=%s',$this->q->study).' AND e.id IN ('.$ids.') ORDER BY e.id FOR UPDATE');}
    public function step(string $id): array {
        $db=$this->q->db;$hint=$this->row($id);$hintPlan=P\Database::json($hint['plan_json']);$final=(int)$hint['cursor_position']+20>=count($hintPlan);return $db->transactional(function()use($db,$id,$hintPlan,$final){if($final)$this->lockPlan($hintPlan);$job=$this->row($id,true);if($job['expires_at']<gmdate('Y-m-d H:i:s')){$db->update('management_exports',array('state'=>'EXPIRED','payload_json'=>null,'plan_json'=>'[]'),$db->prepare('id=%s',$id));return $this->status($this->row($id));}if(!in_array($job['state'],array('PENDING','RUNNING'),true))return $this->status($job);
            $spec=P\Database::json($job['spec_json']);$plan=P\Database::json($job['plan_json']);$rows=P\Database::json($job['payload_json']);$cursor=(int)$job['cursor_position'];
            try{foreach(array_slice($plan,$cursor,20) as $entry){$e=$db->row($db->prepare('SELECT * FROM '.$db->table('study_executions').' WHERE id=%s AND study_id=%s',$entry['id'],$this->q->study));if(!$e||!hash_equals($entry['hash'],$this->fingerprint($e)))throw new P\PersistenceConflict('EXPORT_DATA_CHANGED');if($spec['kind']!=='dictionary')foreach($this->rows($e,$spec) as $row)$rows[]=$row;$cursor++;}
                if($spec['kind']==='audit'&&(int)$job['cursor_position']===0){$global=$db->prepare('study_id=%s AND execution_id IS NULL AND id<=%d',$this->q->study,$spec['cutoff_event']);if(!empty($spec['filters']['execution']))$global.=' AND 0=1';if(!empty($spec['filters']['version']))$global.=$db->prepare(" AND (entity_id=%s OR JSON_UNQUOTE(JSON_EXTRACT(details_json,'$.version'))=%s)",$spec['filters']['version'],$spec['filters']['version']);if(!empty($spec['filters']['cycle']))$global.=$db->prepare(" AND JSON_EXTRACT(details_json,'$.cycle')=%d",$spec['filters']['cycle']);foreach($db->rows('SELECT id,entity_id,action,actor_id,created_at,details_json FROM '.$db->table('management_events').' WHERE '.$global.' ORDER BY id') as $event)$rows[]=array('source'=>'ADMIN','participation_id'=>null,'sequence'=>$event['id'],'action'=>$event['action'],'actor_id'=>$event['actor_id'],'server_at'=>$event['created_at'],'domain_at'=>null,'entity_id'=>$event['entity_id'],'details'=>P\Database::json($event['details_json']));}
                if($spec['kind']==='dictionary'){$rows=$this->q->dictionaryRows($spec['filters']);$cursor=count($plan);}
                $payload=Canonical::json($rows);if(strlen($payload)>33554432)throw new \DomainException('EXPORT_FILTER_REQUIRED');$state=$cursor===count($plan)?'READY':'RUNNING';$manifest=null;
                if($state==='READY'){if(!$this->valid($plan))throw new P\PersistenceConflict('EXPORT_DATA_CHANGED');$manifest=array('contract'=>'EIPSI_STUDY_DATA_V1','study_id'=>$this->q->study,'as_of'=>$job['created_at'].' UTC','filters'=>$spec['filters'],'kind'=>$spec['kind'],'actor_id'=>(int)$job['actor_id'],'participations'=>count($plan),'rows'=>count($rows),'sha256'=>hash('sha256',$payload),'columns'=>$spec['kind']==='responses'?self::COLUMNS:array_values(array_unique(array_merge(array(),...array_map('array_keys',$rows)))),'policy'=>'DO_NOT_USE excluded from analytical datasets; partials only on request.','versions'=>$this->q->context()['versions']);Audit::record($this->q->study,'EXPORT_READY',null,$id,array('count'=>count($rows),'hash'=>$manifest['sha256']));}
                $db->update('management_exports',array('state'=>$state,'payload_json'=>$payload,'cursor_position'=>$cursor,'manifest_json'=>$manifest===null?null:Canonical::json($manifest)),$db->prepare('id=%s',$id));
            }catch(P\PersistenceConflict $e){$db->update('management_exports',array('state'=>'INVALIDATED','payload_json'=>null,'error_code'=>'EXPORT_DATA_CHANGED'),$db->prepare('id=%s',$id));Audit::record($this->q->study,'EXPORT_INVALIDATED',null,$id,array('reason'=>'DATA_CHANGED'));}
            catch(\DomainException $e){$db->update('management_exports',array('state'=>'FAILED','payload_json'=>null,'error_code'=>$e->getMessage()),$db->prepare('id=%s',$id));Audit::record($this->q->study,'EXPORT_FAILED',null,$id,array('reason'=>$e->getMessage()));}
            return $this->status($this->row($id));
        });
    }
    private function rows(array $e,array $spec): array {
        $f=$spec['filters'];$base=array('study_id'=>$e['study_id'],'cycle'=>(int)$e['study_cycle'],'study_version_id'=>$e['study_version_id'],'participation_id'=>$e['id']);$db=$this->q->db;
        if($spec['kind']==='identities'){$p=$e['participant_id']===null?null:$db->row($db->prepare('SELECT email,archived_email,verification_state FROM '.$db->table('participants').' WHERE id=%s',$e['participant_id']));return array($base+array('email'=>$p['email']??null,'archived_email'=>$p['archived_email']??null,'verification'=>$p['verification_state']??null));}
        if($spec['kind']==='progress'){$blocks=array();$page=$this->q->opportunities(array('execution'=>$e['id'],'limit'=>100));do{foreach($page['items'] as $block)$blocks[]=$block;if(!$page['next'])break;$page=$this->q->opportunities(array('execution'=>$e['id'],'limit'=>100,'cursor'=>$page['next']));}while(true);return array($base+array('state'=>$e['state'],'data_policy'=>$e['data_policy'],'created_at'=>$e['created_at'],'finalized_at'=>$e['finalized_at'],'opportunities'=>Query::redact($blocks)));}
        if($spec['kind']==='audit'){
            $out=array();foreach($db->rows($db->prepare('SELECT id,execution_id,entity_id,action,actor_id,created_at,details_json FROM '.$db->table('management_events').' WHERE study_id=%s AND execution_id=%s AND id<=%d ORDER BY id',$this->q->study,$e['id'],$spec['cutoff_event'])) as $r)$out[]=array('source'=>'ADMIN_NATIVE','participation_id'=>$e['id'],'sequence'=>$r['id'],'action'=>$r['action'],'actor_id'=>$r['actor_id'],'server_at'=>$r['created_at'],'domain_at'=>null,'entity_id'=>$r['entity_id'],'details'=>P\Database::json($r['details_json']));
            if($e['data_policy']!=='DO_NOT_USE')foreach($db->rows($db->prepare('SELECT sequence,event_type,server_at,domain_at,block_execution_id,rule_id,decision_id,old_state,new_state,reason FROM '.$db->table('execution_events').' WHERE execution_id=%s AND server_at<=%s ORDER BY sequence',$e['id'],$spec['cutoff_at'])) as $r)$out[]=array('source'=>'STUDY','participation_id'=>$e['id'],'sequence'=>$r['sequence'],'action'=>$r['event_type'],'actor_id'=>0,'server_at'=>$r['server_at'],'domain_at'=>$r['domain_at'],'entity_id'=>$r['block_execution_id'],'details'=>$r);return $out;
        }
        if($spec['kind']==='randomizations'){
            $out=array();foreach($db->rows($db->prepare('SELECT id,block_execution_id,owner_id,scope,algorithm_version,candidates_json,selection_json,created_at FROM '.$db->table('random_decisions').' WHERE execution_id=%s ORDER BY id',$e['id'])) as $r)$out[]=$base+array('level'=>'STUDY','decision_id'=>$r['id'],'opportunity_id'=>$r['block_execution_id'],'attempt_id'=>null,'owner_id'=>$r['owner_id'],'algorithm'=>$r['algorithm_version'],'candidates'=>P\Database::json($r['candidates_json']),'selection'=>P\Database::json($r['selection_json']),'recorded_at'=>$r['created_at']);
            if($this->q->nativeExists())foreach($db->rows($db->prepare('SELECT id FROM '.$db->table('native_executions').' WHERE management_execution=%s ORDER BY id',$e['id'])) as $n){$a=$this->q->attempt($n['id'],false);foreach(array('blocks','option_orders') as $category)foreach($a['metadata']['randomization'][$category]??array() as $owner=>$r)$out[]=$base+array('level'=>$category==='blocks'?'NATIVE_BLOCK':'NATIVE_OPTIONS','decision_id'=>$n['id'].'|'.$owner,'opportunity_id'=>$a['opportunity_id'],'attempt_id'=>$n['id'],'owner_id'=>$owner,'algorithm'=>$r['selection_method']??$a['metadata']['randomization']['contract'],'candidates'=>$r['candidates']??array(),'selection'=>$r['order']??$r['option_ids']??array(),'recorded_at'=>$r['resolved_at']??null);}
            return $out;
        }

        $out=array();$seen=array();if($this->q->nativeExists()){$natives=$db->rows($db->prepare('SELECT id FROM '.$db->table('native_executions')." WHERE management_execution=%s AND state IN ('COMPLETED','LOGICAL_EXIT'".(!empty($f['include_partials'])?",'PARTIAL_SAVED'":'').') ORDER BY id',$e['id']));
            foreach($natives as $n){$a=$this->q->attempt($n['id'],false);if(!empty($f['opportunity'])&&$a['opportunity_id']!==$f['opportunity'])continue;$dictionary=$a['dictionary'];if(!empty($f['assessment'])){$r=$this->q->nativeRecord($n['id']);if(P\Database::json($r['definition_json'])['id']!==$f['assessment'])continue;}
                if($spec['kind']==='dictionary'){foreach($dictionary as $key=>$d){$k=$a['version_id'].'|'.$key;if(isset($seen[$k]))continue;$seen[$k]=true;$out[]=array('study_version_id'=>$e['study_version_id'],'native_version_id'=>$a['version_id'],'definition_hash'=>$a['definition_hash'],'response_key'=>$key)+$d;}continue;}
                foreach($a['rows'] as $row){$d=$dictionary[$row['response_key']]??array();$values=$base+array('opportunity_id'=>$a['opportunity_id'],'occurrence'=>$a['occurrence'],'assessment_id'=>$a['assessment_id'],'native_version_id'=>$a['version_id'],'attempt_id'=>$a['id'],'attempt_state'=>$a['state'],'saved_at'=>$a['saved_at'],'item_id'=>$row['item_id']??null,'response_key'=>$row['response_key'],'variable_name'=>$row['variable_name'],'label'=>$d['label']??null,'type'=>$d['type']??null,'response_status'=>$row['response_status']??'NOT_RECORDED','value'=>$row['value'],'selected_option_id'=>$row['selected_option_id']??null,'definition_hash'=>$a['definition_hash'],'data_policy'=>$e['data_policy']);$out[]=array_replace(array_fill_keys(self::COLUMNS,null),$values);}
            }
        }
        // Domain-native Study responses (without a Native Assessment binding).
        $v=$db->row($db->prepare('SELECT protocol_json FROM '.$db->table('study_versions').' WHERE id=%s',$e['study_version_id']));$d=P\Database::json($v['protocol_json']);$nodes=array_column($d['nodes'],null,'id');$s=P\Database::json($e['checkpoint_json'])['state'];$s['instances']=(new P\BlockExecutionRepository($db))->load($e['id'],$e['study_version_id']);
        foreach($s['responses']??array() as $block=>$responses){$b=$s['instances'][$block]??null;if(!$b||isset($nodes[$b['definition_id']]['metadata']['native_version_id']))continue;if(!empty($f['opportunity'])&&$block!==$f['opportunity'])continue;if(!empty($f['assessment'])&&$b['definition_id']!==$f['assessment'])continue;if($b['state']!=='COMPLETED'&&empty($f['include_partials']))continue;
            foreach($responses as $qid=>$answer){$q=$nodes[$qid]??null;if(!$q)throw new P\IntegrityFailure('EXPORT_QUESTION_MISSING');$content=json_decode($q['content']['snapshot']??'',true);$dict=array('study_version_id'=>$e['study_version_id'],'native_version_id'=>null,'definition_hash'=>$q['content']['sha256'],'response_key'=>$q['response_key'],'item_id'=>$qid,'variable_name'=>$q['response_key'],'label'=>$content['label']??$qid,'type'=>$q['type'],'options'=>$q['options'],'validation'=>$q['validation']);if($spec['kind']==='dictionary'){$out[]=$dict;continue;}$out[]=array_replace(array_fill_keys(self::COLUMNS,null),$base+array('opportunity_id'=>$block,'occurrence'=>$b['occurrence_key'],'assessment_id'=>$b['definition_id'],'attempt_id'=>$block,'attempt_state'=>$b['state'],'saved_at'=>$b['completed_at'],'item_id'=>$qid,'response_key'=>$q['response_key'],'variable_name'=>$q['response_key'],'label'=>$dict['label'],'type'=>$q['type'],'response_status'=>$answer['value']===null?'NO_VALUE_RECORDED':'VALUE_RECORDED','value'=>$answer['value'],'definition_hash'=>$dict['definition_hash'],'data_policy'=>$e['data_policy']));}
        }return $out;
    }
    public function download(string $id,string $format): array {
        if(!in_array($format,array('csv','json'),true))throw new \DomainException('EXPORT_FORMAT_INVALID');$db=$this->q->db;$hint=$this->row($id);$plan=P\Database::json($hint['plan_json']);
        return $db->transactional(function()use($id,$format,$db,$plan){$this->lockPlan($plan);$r=$this->row($id,true);if($r['state']!=='READY'||$r['expires_at']<gmdate('Y-m-d H:i:s')||!$this->valid(P\Database::json($r['plan_json'])))throw new P\PersistenceConflict('EXPORT_UNAVAILABLE_OR_CHANGED');$rows=P\Database::json($r['payload_json']);$manifest=P\Database::json($r['manifest_json']);if(!hash_equals($manifest['sha256'],hash('sha256',Canonical::json($rows))))throw new P\IntegrityFailure('EXPORT_HASH_MISMATCH');Audit::record($this->q->study,'EXPORT_DOWNLOADED',null,$id,array('kind'=>$format,'count'=>count($rows)));
            if($format==='json')return array('filename'=>$id.'.json','mime'=>'application/json','content'=>wp_json_encode(array('manifest'=>$manifest,'rows'=>$rows),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
            $columns=$manifest['columns'];$stream=fopen('php://temp','w+');fputcsv($stream,$columns,',','"','');foreach($rows as $row){$cells=array();foreach($columns as $key){$v=$row[$key]??null;if(is_bool($v))$v=$v?'true':'false';if(is_array($v))$v=Canonical::json($v);if(is_string($v)&&preg_match('/^[\s\x{FEFF}\x{200B}]*[=+\-@]/u',$v))$v="'".$v;$cells[]=$v;}fputcsv($stream,$cells,',','"','');}rewind($stream);$content=stream_get_contents($stream);fclose($stream);return array('filename'=>$id.'.csv','mime'=>'text/csv;charset=utf-8','content'=>$content);
        });
    }
}
